"""Query execution for minisql.

The public entry point is :func:`execute`, which parses a ``SELECT``
statement, loads the referenced CSV table, validates the query, and runs it.
Every problem with the query is reported as :class:`minisql.errors.QueryError`.
"""

import csv
import os
import re
from functools import cmp_to_key

from .ast import (
    Between,
    Binary,
    Column,
    FuncCall,
    InList,
    IsNull,
    Like,
    Literal,
    Star,
    Unary,
    column_refs,
    contains_aggregate,
    is_aggregate,
    walk,
)
from .errors import QueryError
from .evaluator import evaluate
from .parser import parse

_INT_RE = re.compile(r"-?[0-9]+")
_FLOAT_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")


# ---------------------------------------------------------------------------
# Table loading
# ---------------------------------------------------------------------------


def _convert(field):
    """Convert one CSV field to an int, float, string, or None."""
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _FLOAT_RE.fullmatch(field):
        return float(field)
    return field


def _load_table(directory, table):
    """Load ``table.csv`` from *directory*.

    Returns ``(header, actual_by_lower, rows)`` where *header* keeps the
    header's original spelling, *actual_by_lower* maps lower-case names to
    that spelling, and *rows* is a list of dicts keyed by lower-case name.
    """
    path = os.path.join(os.fspath(directory), table + ".csv")
    try:
        handle = open(path, "r", newline="", encoding="utf-8-sig")
    except OSError as exc:
        raise QueryError("unknown table: {}".format(table)) from exc

    try:
        with handle:
            reader = csv.reader(handle)
            try:
                header = next(reader)
            except StopIteration:
                raise QueryError("table has no header: {}".format(table))

            if not header:
                raise QueryError("table has no header: {}".format(table))

            actual_by_lower = {}
            keys = []
            for name in header:
                key = name.lower()
                keys.append(key)
                actual_by_lower[key] = name

            rows = []
            for raw in reader:
                row = {}
                for index, key in enumerate(keys):
                    if index < len(raw):
                        row[key] = _convert(raw[index])
                    else:
                        row[key] = None
                rows.append(row)
    except QueryError:
        raise
    except (OSError, UnicodeError, csv.Error) as exc:
        raise QueryError("cannot read table {}: {}".format(table, exc)) from exc

    return header, actual_by_lower, rows


# ---------------------------------------------------------------------------
# Structural helpers
# ---------------------------------------------------------------------------


def _value_key(value):
    """Return a hashable, type-aware key for grouping and DISTINCT.

    Numbers compare and hash numerically, so ``1`` and ``1.0`` share a key.
    Booleans, ``None``, and strings each get their own category.
    """
    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("bool", value)
    if isinstance(value, (int, float)):
        return ("num", value)
    if isinstance(value, str):
        return ("str", value)
    return ("other", type(value).__name__, repr(value))


def _expr_key(node):
    """Return a hashable structural key for an expression.

    ``text`` is ignored. Column and function names are case-insensitive, as
    required for matching query columns and GROUP BY expressions.
    """
    if node is None:
        return ("none",)
    if isinstance(node, Literal):
        return ("literal", _value_key(node.value))
    if isinstance(node, Column):
        return ("column", node.name.lower())
    if isinstance(node, Star):
        return ("star",)
    if isinstance(node, Unary):
        return ("unary", node.op.upper(), _expr_key(node.operand))
    if isinstance(node, Binary):
        return (
            "binary",
            node.op.upper(),
            _expr_key(node.left),
            _expr_key(node.right),
        )
    if isinstance(node, IsNull):
        return ("isnull", node.negated, _expr_key(node.operand))
    if isinstance(node, InList):
        return (
            "in",
            node.negated,
            _expr_key(node.operand),
            tuple(_expr_key(item) for item in node.items),
        )
    if isinstance(node, Between):
        return (
            "between",
            node.negated,
            _expr_key(node.operand),
            _expr_key(node.low),
            _expr_key(node.high),
        )
    if isinstance(node, Like):
        return (
            "like",
            node.negated,
            _expr_key(node.operand),
            _expr_key(node.pattern),
        )
    if isinstance(node, FuncCall):
        return (
            "func",
            node.name.upper(),
            node.star,
            tuple(_expr_key(arg) for arg in node.args),
        )
    return ("unknown", type(node).__name__, repr(node))


def _sort_category(value):
    """Classify a value for ORDER BY; ``None`` means an unsupported type."""
    if isinstance(value, bool):
        return "bool"
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "string"
    return None


def _compare_scalar(left, right):
    """Compare two non-``None``-aware values for sorting.

    ``None`` sorts before everything else; the caller flips the result for a
    descending sort.
    """
    if left is None and right is None:
        return 0
    if left is None:
        return -1
    if right is None:
        return 1

    left_category = _sort_category(left)
    right_category = _sort_category(right)
    if left_category is None or right_category is None:
        raise QueryError("cannot order by this value")
    if left_category != right_category:
        raise QueryError("cannot compare values of different types")
    if left < right:
        return -1
    if left > right:
        return 1
    return 0


# ---------------------------------------------------------------------------
# Validation
# ---------------------------------------------------------------------------


def _validate_aggregates(query):
    """Check aggregate placement, nesting, and arity."""
    if contains_aggregate(query.where):
        raise QueryError("aggregate functions are not allowed in WHERE")
    if any(contains_aggregate(expr) for expr in query.group_by):
        raise QueryError("aggregate functions are not allowed in GROUP BY")

    roots = [item.expr for item in query.items if not isinstance(item.expr, Star)]
    roots.append(query.where)
    roots.extend(query.group_by)
    roots.append(query.having)
    roots.extend(item.expr for item in query.order_by)

    for root in roots:
        for node in walk(root):
            if not is_aggregate(node):
                continue
            name = node.name.upper()
            if node.star:
                if name != "COUNT":
                    raise QueryError("{} does not accept *".format(name))
                if any(not isinstance(arg, Star) for arg in node.args):
                    raise QueryError("{} does not accept *".format(name))
                continue
            if len(node.args) != 1:
                raise QueryError(
                    "{} takes exactly one argument".format(name)
                )
            if any(contains_aggregate(arg) for arg in node.args):
                raise QueryError(
                    "nested aggregate functions are not allowed"
                )


def _build_outputs(query, header, actual_by_lower):
    """Build the output columns as ``(name, expression)`` pairs."""
    outputs = []
    for item in query.items:
        expr = item.expr
        if isinstance(expr, Star):
            for name in header:
                outputs.append((name, Column(text=name, name=name)))
            continue

        if item.alias is not None:
            output_name = item.alias
        elif isinstance(expr, Column):
            actual = actual_by_lower.get(expr.name.lower())
            if actual is None:
                raise QueryError("unknown column: {}".format(expr.name))
            output_name = actual
        else:
            output_name = expr.text
        outputs.append((output_name, expr))
    return outputs


def _resolve_order_by(query, outputs):
    """Resolve ORDER BY items into output references or expressions."""
    output_names = [name.lower() for name, _ in outputs]
    specs = []
    for item in query.order_by:
        expr = item.expr

        if isinstance(expr, Column):
            try:
                index = output_names.index(expr.name.lower())
            except ValueError:
                index = None
            if index is not None:
                specs.append(("output", index, item.descending))
                continue

        if (
            isinstance(expr, Literal)
            and isinstance(expr.value, int)
            and not isinstance(expr.value, bool)
        ):
            position = expr.value
            if position < 1 or position > len(outputs):
                raise QueryError(
                    "ORDER BY position {} is out of range".format(position)
                )
            specs.append(("output", position - 1, item.descending))
            continue

        specs.append(("expr", expr, item.descending))
    return specs


def _validate_column_references(query, outputs, order_specs, actual_by_lower):
    """Ensure every input column reference exists in the table."""

    def check(expr):
        for column in column_refs(expr):
            if column.name.lower() not in actual_by_lower:
                raise QueryError("unknown column: {}".format(column.name))

    for _, expr in outputs:
        check(expr)
    check(query.where)
    for expr in query.group_by:
        check(expr)
    check(query.having)
    for kind, payload, _ in order_specs:
        if kind == "expr":
            check(payload)


def _is_grouped(query):
    """Return whether the query is an aggregate/grouped query."""
    if query.group_by:
        return True
    if any(
        contains_aggregate(item.expr)
        for item in query.items
        if not isinstance(item.expr, Star)
    ):
        return True
    if contains_aggregate(query.having):
        return True
    if any(contains_aggregate(item.expr) for item in query.order_by):
        return True
    return False


def _check_grouped(expr, group_keys, allowed_columns):
    """Validate a non-aggregate expression against the GROUP BY list."""
    if expr is None:
        return
    if is_aggregate(expr):
        return
    if _expr_key(expr) in group_keys:
        return
    if isinstance(expr, Literal):
        return
    if isinstance(expr, Column):
        if expr.name.lower() in allowed_columns:
            return
        raise QueryError(
            "column {} must appear in GROUP BY or be used in an aggregate".format(
                expr.name
            )
        )

    from .ast import children

    for child in children(expr):
        _check_grouped(child, group_keys, allowed_columns)


# ---------------------------------------------------------------------------
# Execution
# ---------------------------------------------------------------------------


def execute(sql, directory="."):
    """Execute *sql* against the CSV files in *directory*.

    Returns ``(columns, rows)`` where *columns* is a list of output names and
    *rows* is a list of tuples.
    """
    query = parse(sql)

    header, actual_by_lower, input_rows = _load_table(directory, query.table)

    _validate_aggregates(query)
    outputs = _build_outputs(query, header, actual_by_lower)
    order_specs = _resolve_order_by(query, outputs)
    _validate_column_references(query, outputs, order_specs, actual_by_lower)

    grouped = _is_grouped(query)
    if grouped:
        group_keys = {_expr_key(expr) for expr in query.group_by}
        allowed_columns = {
            expr.name.lower()
            for expr in query.group_by
            if isinstance(expr, Column)
        }
        for _, expr in outputs:
            _check_grouped(expr, group_keys, allowed_columns)
        _check_grouped(query.having, group_keys, allowed_columns)
        for kind, payload, _ in order_specs:
            if kind == "expr":
                _check_grouped(payload, group_keys, allowed_columns)

    # WHERE is evaluated per input row, before grouping.
    if query.where is None:
        filtered_rows = input_rows
    else:
        filtered_rows = [
            row
            for row in input_rows
            if evaluate(query.where, row, None) is True
        ]

    # Build the (representative row, group) contexts to project from.
    if grouped:
        if query.group_by:
            groups = {}
            for row in filtered_rows:
                key = tuple(
                    _value_key(evaluate(expr, row, None))
                    for expr in query.group_by
                )
                groups.setdefault(key, []).append(row)
            contexts = [
                (members[0], members) for members in groups.values()
            ]
        elif filtered_rows:
            contexts = [(filtered_rows[0], filtered_rows)]
        else:
            contexts = [({}, [])]
    else:
        contexts = [(row, None) for row in filtered_rows]

    # Project and apply HAVING.
    records = []
    for representative, group in contexts:
        if query.having is not None:
            if evaluate(query.having, representative, group) is not True:
                continue
        values = tuple(
            evaluate(expr, representative, group) for _, expr in outputs
        )
        records.append((values, representative, group))

    # DISTINCT keeps the first occurrence in the current order.
    if query.distinct:
        seen = set()
        unique_records = []
        for record in records:
            key = tuple(_value_key(value) for value in record[0])
            if key in seen:
                continue
            seen.add(key)
            unique_records.append(record)
        records = unique_records

    # ORDER BY, with type checking before sorting so mixed types always fail.
    if order_specs:
        keyed = []
        for values, representative, group in records:
            keys = []
            for kind, payload, _ in order_specs:
                if kind == "output":
                    keys.append(values[payload])
                else:
                    keys.append(evaluate(payload, representative, group))
            keyed.append((keys, values, representative, group))

        for index, (_, _, _) in enumerate(order_specs):
            categories = set()
            for keys, _, _, _ in keyed:
                value = keys[index]
                if value is None:
                    continue
                category = _sort_category(value)
                if category is None:
                    raise QueryError("cannot order by this value")
                categories.add(category)
            if len(categories) > 1:
                raise QueryError("cannot compare values of different types")

        def compare(left, right):
            for index, (_, _, descending) in enumerate(order_specs):
                result = _compare_scalar(
                    left[0][index], right[0][index]
                )
                if result:
                    return -result if descending else result
            return 0

        keyed.sort(key=cmp_to_key(compare))
        records = [
            (values, representative, group)
            for _, values, representative, group in keyed
        ]

    # LIMIT / OFFSET are applied last.
    offset = query.offset if query.offset is not None else 0
    limit = query.limit
    if offset < 0:
        raise QueryError("OFFSET must not be negative")
    if limit is not None and limit < 0:
        raise QueryError("LIMIT must not be negative")

    if offset:
        records = records[offset:]
    if limit is not None:
        records = records[:limit]

    columns = [name for name, _ in outputs]
    rows = [values for values, _, _ in records]
    return columns, rows

